class MinMaxStack {
  constructor() {
    this.items = [];     // each entry: [value, min so far, max so far]
  }
  push(x) {
    if (this.items.length === 0) {
      this.items.push([x, x, x]);
    } else {
      const [, min, max] = this.items[this.items.length - 1];
      this.items.push([x, Math.min(min, x), Math.max(max, x)]);
    }
  }
  pop() {
    this.items.pop();    // the entry below still knows its own min and max
  }
  top() {
    return this.items[this.items.length - 1][0];
  }
  getMin() {
    return this.items[this.items.length - 1][1];
  }
  getMax() {
    return this.items[this.items.length - 1][2];
  }
}

