class MinMaxStack {
    private final Deque<int[]> items = new ArrayDeque<>();   // {value, min so far, max so far}

    public void push(int x) {
        if (items.isEmpty()) {
            items.push(new int[]{x, x, x});
        } else {
            int[] below = items.peek();
            items.push(new int[]{x, Math.min(below[1], x), Math.max(below[2], x)});
        }
    }

    public void pop() {
        items.pop();             // the entry below still knows its own min and max
    }

    public int top() {
        return items.peek()[0];
    }

    public int getMin() {
        return items.peek()[1];
    }

    public int getMax() {
        return items.peek()[2];
    }
}

