class MinMaxStack {
  constructor() {
    this.items = [];
    this.mins = [];      // top of mins = the current minimum
    this.maxs = [];      // top of maxs = the current maximum
  }
  push(x) {
    this.items.push(x);
    if (this.mins.length === 0 || x <= this.getMin()) this.mins.push(x);
    if (this.maxs.length === 0 || x >= this.getMax()) this.maxs.push(x);
  }
  pop() {
    const x = this.items.pop();
    if (x === this.getMin()) this.mins.pop();
    if (x === this.getMax()) this.maxs.pop();
  }
  top() {
    return this.items[this.items.length - 1];
  }
  getMin() {
    return this.mins[this.mins.length - 1];
  }
  getMax() {
    return this.maxs[this.maxs.length - 1];
  }
}

class MinMaxStack:
    def __init__(self):
        self.items = []
        self.mins = []           # top of mins = the current minimum
        self.maxs = []           # top of maxs = the current maximum

    def push(self, x):
        self.items.append(x)
        if not self.mins or x <= self.mins[-1]:
            self.mins.append(x)
        if not self.maxs or x >= self.maxs[-1]:
            self.maxs.append(x)

    def pop(self):
        x = self.items.pop()
        if x == self.mins[-1]:
            self.mins.pop()
        if x == self.maxs[-1]:
            self.maxs.pop()

    def top(self):
        return self.items[-1]

    def getMin(self):
        return self.mins[-1]

    def getMax(self):
        return self.maxs[-1]

class MinMaxStack {
    private final Deque<Integer> items = new ArrayDeque<>();
    private final Deque<Integer> mins = new ArrayDeque<>();   // top of mins = the current minimum
    private final Deque<Integer> maxs = new ArrayDeque<>();   // top of maxs = the current maximum

    public void push(int x) {
        items.push(x);
        if (mins.isEmpty() || x <= mins.peek()) mins.push(x);
        if (maxs.isEmpty() || x >= maxs.peek()) maxs.push(x);
    }

    public void pop() {
        int x = items.pop();
        if (x == mins.peek()) mins.pop();
        if (x == maxs.peek()) maxs.pop();
    }

    public int top() {
        return items.peek();
    }

    public int getMin() {
        return mins.peek();
    }

    public int getMax() {
        return maxs.peek();
    }
}

class MinMaxStack {
    stack<int> items, mins, maxs;    // tops of mins and maxs: the current min and max

public:
    void push(int x) {
        items.push(x);
        if (mins.empty() || x <= mins.top()) mins.push(x);
        if (maxs.empty() || x >= maxs.top()) maxs.push(x);
    }

    void pop() {
        int x = items.top();
        items.pop();
        if (x == mins.top()) mins.pop();
        if (x == maxs.top()) maxs.pop();
    }

    int top() {
        return items.top();
    }

    int getMin() {
        return mins.top();
    }

    int getMax() {
        return maxs.top();
    }
};
